(39061, 'Leviticus 7:38', 'Leviticus', 7, 38, 'په دښته کې د سینا په غره باندې څښتن موسی ته دا حکمونه ورکړل او په هماغه ورځ موسی د اسراییلو قوم ته وویل چې خپلې نذرانې راوړي.', 'په دشته کې د سینا په غره باندې چشتن موسی ته دا حکمونه ورکرل او په هماغه ورج موسی د اسراییلو قوم ته وویل چې خپلې نذرانې راوری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_7_38.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237840, 1761237840),
(39062, 'Psalms 119:1', 'Psalms', 119, 1, 'بختور دي هغه خلک چې ژوندون یې دی بې‌عیبه چې تېروي خپل ژوند د څښتن د شریعت له مخې', 'بختور دی هغه خلک چې ژوندون یې دی بې‌عیبه چې تېروی خپل ژوند د چشتن د شریعت له مخې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_119_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39063, 'Psalms 119:2', 'Psalms', 119, 2, 'بختور دي هغه خلک چې په حکمونو یې عمل کوي چې څوک رجوع کوي هغه ته د زړه له کومي څخه', 'بختور دی هغه خلک چې په حکمونو یې عمل کوی چې چوک رجوع کوی هغه ته د زره له کومی چخه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_119_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39064, 'Psalms 119:3', 'Psalms', 119, 3, 'هېڅکله نه کوي بدي هغوی هغوی روان وي د څښتن په لاره', 'هېچکله نه کوی بدی هغوی هغوی روان وی د چشتن په لاره', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_119_3.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237840, 1761237840),
(39065, 'Psalms 119:4', 'Psalms', 119, 4, 'خپل قوانین دې دي راکړي مونږ ته ای څښتنه چې اطاعت یې وکړو په وفادارۍ سره', 'خپل قوانین دې دی راکری مونز ته ای چشتنه چې اطاعت یې وکرو په وفاداری سره', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_119_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39066, 'Psalms 119:5', 'Psalms', 119, 5, 'کاشکې چې زه وفادار واوسم چې په قوانینو دې عمل وکړمه', 'کاشکې چې زه وفادار واوسم چې په قوانینو دې عمل وکرمه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_119_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39067, 'Psalms 119:6', 'Psalms', 119, 6, 'که زه عمل وکړمه ستا ټولو حکمونو باندې نو بیا به د شرم سره مخ نه شمه', 'که زه عمل وکرمه ستا تولو حکمونو باندې نو بیا به د شرم سره مخ نه شمه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_119_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39068, 'Psalms 119:7', 'Psalms', 119, 7, 'څنګه چې زده کړمه رښتیني قوانین د ستا نو په پاک زړه به دې ثنا وایمه', 'چنګه چې زده کرمه رشتینی قوانین د ستا نو په پاک زره به دې ثنا وایمه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_119_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
