(39073, 'Psalms 119:12', 'Psalms', 119, 12, 'زه ستا ثنا وایمه ای څښتنه ماته رازده کړه ته دې خپل قوانین', 'زه ستا ثنا وایمه ای چشتنه ماته رازده کره ته دې خپل قوانین', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_119_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39074, 'Psalms 119:13', 'Psalms', 119, 13, 'بیانومه زه په لوړ اواز ټول قوانین چې دې راکړي مونږ ته', 'بیانومه زه په لور اواز تول قوانین چې دې راکری مونز ته', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_119_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
